{
"user_intent": "创建一个 L 形角码零件，包含两个方向的贯穿孔。水平边长 50mm、宽 30mm、厚 5mm；竖直边高 40mm、宽 30mm、厚 5mm。水平边上有 2 个直径 6mm 的孔，竖直边上有 1 个直径 6mm 的孔。",
"notes": "单位换算：所有尺寸从 mm 转换为 m。建模策略：先在前视基准面绘制 L 形轮廓（外轮廓 50x40，内凹角位置根据厚度 5mm 和宽度 30mm 推算），一次拉伸 30mm 宽度形成实体。然后在顶面和前面分别画圆并切除生成孔。",
"steps": [
{
"operation": "new_part",
"description": "新建零件文档",
"params": {}
},
{
"operation": "select_plane",
"description": "选择前视基准面绘制 L 形截面",
"params": {
"index": 0
}
},
{
"operation": "sketch_line",
"description": "画 L 形轮廓第 1 段：底边 (0,0) 到 (0.05,0)",
"params": {
"x1": 0.0,
"y1": 0.0,
"x2": 0.05,
"y2": 0.0
}
},
{
"operation": "sketch_line",
"description": "画 L 形轮廓第 2 段：右侧竖边 (0.05,0) 到 (0.05,0.005)",
"params": {
"x1": 0.05,
"y1": 0.0,
"x2": 0.05,
"y2": 0.005
}
},
{
"operation": "sketch_line",
"description": "画 L 形轮廓第 3 段：内凹横边 (0.05,0.005) 到 (0.005,0.005)",
"params": {
"x1": 0.05,
"y1": 0.005,
"x2": 0.005,
"y2": 0.005
}
},
{
"operation": "sketch_line",
"description": "画 L 形轮廓第 4 段：内凹竖边 (0.005,0.005) 到 (0.005,0.04)",
"params": {
"x1": 0.005,
"y1": 0.005,
"x2": 0.005,
"y2": 0.04
}
},
{
"operation": "sketch_line",
"description": "画 L 形轮廓第 5 段：顶部横边 (0.005,0.04) 到 (0.0,0.04)",
"params": {
"x1": 0.005,
"y1": 0.04,
"x2": 0.0,
"y2": 0.04
}
},
{
"operation": "sketch_line",
"description": "画 L 形轮廓第 6 段：左侧竖边 (0,0.04) 回到 (0,0) 闭合",
"params": {
"x1": 0.0,
"y1": 0.04,
"x2": 0.0,
"y2": 0.0
}
},
{
"operation": "feature_extrusion",
"description": "拉伸 L 形截面 30mm 宽度形成角码实体",
"params": {
"depth": 0.03
}
},
{
"operation": "select_face_and_sketch",
"description": "选中角码顶面（法向-Y）准备画水平边的 2 个孔",
"params": {
"rx": 0.025,
"ry": 0.04,
"rz": 0.015,
"dx": 0.0,
"dy": -1.0,
"dz": 0.0
}
},
{
"operation": "sketch_circle",
"description": "画第 1 个孔：距竖直边外侧 20mm，即 X=0.02，Y=0（顶面），Z=0.015（宽度中线）",
"params": {
"cx": 0.02,
"cy": 0.0,
"cz": 0.015,
"radius": 0.003
}
},
{
"operation": "sketch_circle",
"description": "画第 2 个孔：距竖直边外侧 38mm，即 X=0.038，Y=0（顶面），Z=0.015（宽度中线）",
"params": {
"cx": 0.038,
"cy": 0.0,
"cz": 0.015,
"radius": 0.003
}
},
{
"operation": "feature_cut_extrusion",
"description": "贯穿切除顶面的 2 个圆孔",
"params": {
"depth": 0.005,
"endCondition": "through_all"
}
},
{
"operation": "select_face_and_sketch",
"description": "选中角码前面（法向+Z）准备画竖直边的 1 个孔",
"params": {
"rx": 0.005,
"ry": 0.025,
"rz": 0.04,
"dx": 0.0,
"dy": 0.0,
"dz": -1.0
}
},
{
"operation": "sketch_circle",
"description": "画竖直边孔：距底面 25mm (Y=0.025)，宽度中线 (X=0.015)",
"params": {
"cx": 0.015,
"cy": 0.025,
"cz": 0.0,
"radius": 0.003
}
},
{
"operation": "feature_cut_extrusion",
"description": "贯穿切除前面的圆孔",
"params": {
"depth": 0.005,
"endCondition": "through_all"
}
}
]
}

{
"user_intent": "创建一个 L 形角码零件，包含两个方向的贯穿孔。水平边和竖直边厚度均为 5mm，宽度均为 30mm。水平边外侧长 50mm，竖直边外侧高 40mm。水平边上有 2 个直径 6mm 的孔，竖直边上有 1 个直径 6mm 的孔。",
"notes": "建模策略：先在上视基准面绘制 L 形轮廓（外轮廓 + 内圆角过渡），一次拉伸 5mm 生成实体。然后分别在前视基准面（对应水平边顶面）和右视基准面（对应竖直边侧面）绘制孔的草图，使用完全贯穿切除。所有尺寸已转换为米。",
"steps": [
{
"operation": "new_part",
"description": "新建零件文档",
"params": {}
},
{
"operation": "select_plane",
"description": "选择上视基准面作为草图平面，用于绘制 L 形截面",
"params": {
"index": 1
}
},
{
"operation": "sketch_line",
"description": "画 L 形外轮廓第一段：从原点向右画水平边底边 (50mm)",
"params": {
"x1": 0.0,
"y1": 0.0,
"x2": 0.05,
"y2": 0.0
}
},
{
"operation": "sketch_line",
"description": "画 L 形外轮廓第二段：向上画竖直边右侧边 (40mm)",
"params": {
"x1": 0.05,
"y1": 0.0,
"x2": 0.05,
"y2": 0.04
}
},
{
"operation": "sketch_line",
"description": "画 L 形外轮廓第三段：向左画竖直边顶边 (30mm 宽)",
"params": {
"x1": 0.05,
"y1": 0.04,
"x2": 0.02,
"y2": 0.04
}
},
{
"operation": "sketch_line",
"description": "画 L 形外轮廓第四段：向下画内拐角竖直线 (25mm = 40-15)",
"params": {
"x1": 0.02,
"y1": 0.04,
"x2": 0.02,
"y2": 0.015
}
},
{
"operation": "sketch_line",
"description": "画 L 形外轮廓第五段：向左画内拐角水平线 (20mm = 50-30)",
"params": {
"x1": 0.02,
"y1": 0.015,
"x2": 0.0,
"y2": 0.015
}
},
{
"operation": "sketch_line",
"description": "画 L 形外轮廓第六段：向下闭合回原点 (15mm)",
"params": {
"x1": 0.0,
"y1": 0.015,
"x2": 0.0,
"y2": 0.0
}
},
{
"operation": "feature_extrusion",
"description": "拉伸 L 形草图生成 5mm 厚的实体",
"params": {
"depth": 0.005
}
},
{
"operation": "select_plane",
"description": "选择前视基准面进入草图，准备在水平边上画孔（注意：前视面对应模型 XZ 平面，Y=0，正好投影到水平边的上表面位置进行切除）",
"params": {
"index": 0
}
},
{
"operation": "sketch_circle",
"description": "画水平边第 1 个孔：距竖直边外侧 20mm，位于宽度中线 (Y=15mm)，但在前视草图中 Y 坐标对应模型 Z(厚度方向)，X 对应模型 X。孔心 X=0.02, Y(草图)=0.0025(厚度一半，确保居中)",
"params": {
"cx": 0.02,
"cy": 0.0025,
"radius": 0.003
}
},
{
"operation": "sketch_circle",
"description": "画水平边第 2 个孔：距竖直边外侧 38mm，孔心 X=0.038, Y(草图)=0.0025",
"params": {
"cx": 0.038,
"cy": 0.0025,
"radius": 0.003
}
},
{
"operation": "feature_cut_extrusion",
"description": "完全贯穿切除水平边上的两个孔",
"params": {
"endCondition": "through_all"
}
},
{
"operation": "select_plane",
"description": "选择右视基准面进入草图，准备在竖直边上画孔（右视面对应模型 YZ 平面，X=0，投影到竖直边侧面）",
"params": {
"index": 2
}
},
{
"operation": "sketch_circle",
"description": "画竖直边上的孔：距底面 25mm (模型 Y=0.025)，位于宽度中线。在右视草图中，Y 轴对应模型 Y(高度)，X 轴对应模型 -Z(厚度负向)。孔心 Y=0.025, X(草图)=-0.0025(厚度一半)",
"params": {
"cx": -0.0025,
"cy": 0.025,
"radius": 0.003
}
},
{
"operation": "feature_cut_extrusion",
"description": "完全贯穿切除竖直边上的孔",
"params": {
"endCondition": "through_all"
}
}
]
}

{
"user_intent": "创建一个外径 40mm、内径 20mm、厚 10mm 的隔套（圆环），并对两个端面的外圆边进行 C1mm 倒角。",
"notes": "建模策略：在前视基准面绘制两个同心圆（外圆 R20mm，内圆 R10mm），一次拉伸 10mm 形成圆环实体。然后使用射线选择方式分别对前端面和后端面的外圆边进行 C1mm 倒角。单位已换算为米。",
"steps": [
{
"operation": "new_part",
"description": "新建零件文档",
"params": {}
},
{
"operation": "select_plane",
"description": "选择前视基准面进入草图编辑",
"params": {
"index": 0
}
},
{
"operation": "sketch_circle",
"description": "绘制外圆轮廓，半径 20mm (0.02m)",
"params": {
"cx": 0.0,
"cy": 0.0,
"radius": 0.02
}
},
{
"operation": "sketch_circle",
"description": "绘制内圆轮廓，半径 10mm (0.01m)，与外圆同心",
"params": {
"cx": 0.0,
"cy": 0.0,
"radius": 0.01
}
},
{
"operation": "feature_extrusion",
"description": "拉伸草图形成厚度 10mm 的圆环隔套",
"params": {
"depth": 0.01
}
},
{
"operation": "feature_chamfer",
"description": "对前端面的外圆边进行 C1mm 倒角 (使用射线选择)",
"params": {
"type": "equal_distance",
"distance1": 0.001,
"edgeSelection": "ray",
"rx": 0.025,
"ry": 0.001,
"rz": 0.0,
"dx": -1.0,
"dy": -1.0,
"dz": 0.0
}
},
{
"operation": "feature_chamfer",
"description": "对后端面的外圆边进行 C1mm 倒角 (使用射线选择)",
"params": {
"type": "equal_distance",
"distance1": 0.001,
"edgeSelection": "ray",
"rx": 0.025,
"ry": 0.009,
"rz": 0.0,
"dx": -1.0,
"dy": 1.0,
"dz": 0.0
}
}
]
}

{
"user_intent": "创建一个外径 40mm、内径 20mm、厚 10mm 的隔套（圆环），并对两个端面的外圆边进行 C1mm 倒角。",
"notes": "建模策略：利用同心圆草图一次拉伸生成圆环实体。倒角操作针对圆柱体外侧的上下两条边，由于是圆柱体局部选边，必须使用射线方式 (edgeSelection='ray') 而非语义名称。单位已统一转换为米。",
"steps": [
{
"description": "新建零件文档",
"operation": "new_part",
"params": {}
},
{
"description": "选择前视基准面绘制草图",
"operation": "select_plane",
"params": {
"index": 0
}
},
{
"description": "绘制同心圆：外圆半径 20mm，内圆半径 10mm",
"operation": "sketch_circle",
"params": {
"cx": 0,
"cy": 0,
"radius": 0.02
}
},
{
"description": "绘制内孔圆（与外圆同心，形成闭环轮廓）",
"operation": "sketch_circle",
"params": {
"cx": 0,
"cy": 0,
"radius": 0.01
}
},
{
"description": "拉伸草图形成厚度 10mm 的圆环隔套",
"operation": "feature_extrusion",
"params": {
"depth": 0.01
}
},
{
"description": "对顶面外圆边做 C1mm 倒角 (射线：从上方斜向射入)",
"operation": "feature_chamfer",
"params": {
"type": "equal_distance",
"distance1": 0.001,
"edgeSelection": "ray",
"rx": 0.025,
"ry": 0.011,
"rz": 0,
"dx": -1,
"dy": -1,
"dz": 0
}
},
{
"description": "对底面外圆边做 C1mm 倒角 (射线：从下方斜向射入)",
"operation": "feature_chamfer",
"params": {
"type": "equal_distance",
"distance1": 0.001,
"edgeSelection": "ray",
"rx": 0.025,
"ry": -0.011,
"rz": 0,
"dx": -1,
"dy": 1,
"dz": 0
}
}
]
}

{
"user_intent": "创建一个 120x80x6mm 的安装板，四个竖直棱边倒 R8 圆角，四个角有距边 12mm 的 Ø7 贯穿孔，中央有一个 40x20mm 的矩形贯穿窗口。",
"notes": "所有尺寸已转换为米。建模策略：1. 在上视基准面绘制外轮廓（含四个角的安装孔），一次拉伸成型；2. 在同一面上绘制中央矩形窗口草图，执行贯穿切除；3. 对四条竖直棱边应用圆角。孔位置计算：板宽 80mm，孔心距边 12mm，则 Y 坐标为 ±(40-12)=±28mm；板长 120mm，X 坐标为 ±(60-12)=±48mm。",
"steps": [
{
"operation": "new_part",
"description": "新建零件文档",
"params": {}
},
{
"operation": "select_plane",
"description": "选择上视基准面作为草图平面",
"params": {
"index": 1
}
},
{
"operation": "sketch_rectangle",
"description": "绘制安装板外轮廓 (120x80mm)",
"params": {
"x1": -0.06,
"y1": -0.04,
"x2": 0.06,
"y2": 0.04
}
},
{
"operation": "sketch_circles",
"description": "绘制四个角的安装孔 (Ø7)，孔心距相邻边 12mm",
"params": {
"circles": [
{
"cx": -0.048,
"cy": 0.028,
"cz": 0,
"radius": 0.0035
},
{
"cx": 0.048,
"cy": 0.028,
"cz": 0,
"radius": 0.0035
},
{
"cx": -0.048,
"cy": -0.028,
"cz": 0,
"radius": 0.0035
},
{
"cx": 0.048,
"cy": -0.028,
"cz": 0,
"radius": 0.0035
}
]
}
},
{
"operation": "feature_extrusion",
"description": "拉伸形成板主体并自动生成四个安装孔 (深度 6mm)",
"params": {
"depth": 0.006
}
},
{
"operation": "select_plane",
"description": "再次选择上视基准面绘制中央窗口",
"params": {
"index": 1
}
},
{
"operation": "sketch_rectangle",
"description": "绘制中央矩形窗口轮廓 (40x20mm)",
"params": {
"x1": -0.02,
"y1": -0.01,
"x2": 0.02,
"y2": 0.01
}
},
{
"operation": "feature_cut_extrusion",
"description": "切除中央矩形窗口 (完全贯穿)",
"params": {
"depth": 0.001,
"endCondition": "through_all"
}
},
{
"operation": "feature_fillet",
"description": "对左前竖直棱边做 R8 圆角",
"params": {
"radius": 0.008,
"edgeSelection": "top_front_left"
}
},
{
"operation": "feature_fillet",
"description": "对右前竖直棱边做 R8 圆角",
"params": {
"radius": 0.008,
"edgeSelection": "top_front_right"
}
},
{
"operation": "feature_fillet",
"description": "对左后竖直棱边做 R8 圆角",
"params": {
"radius": 0.008,
"edgeSelection": "top_back_left"
}
},
{
"operation": "feature_fillet",
"description": "对右后竖直棱边做 R8 圆角",
"params": {
"radius": 0.008,
"edgeSelection": "top_back_right"
}
}
]
}

{
"user_intent": "创建一个 120x80x6mm 的安装板，四个角做 R8 圆角，四个角各有一个距边 12mm 的 Ø7 贯穿孔，中央开一个 40x20mm 的矩形窗口。",
"notes": "所有尺寸已转换为米。建模策略：先画带孔和窗口的完整轮廓草图，一次拉伸成型，最后对竖直棱边做圆角。这样特征树最简洁。",
"steps": [
{
"operation": "new_part",
"description": "新建零件文档",
"params": {}
},
{
"operation": "select_plane",
"description": "选择前视基准面作为草图平面",
"params": {
"index": 0
}
},
{
"operation": "sketch_rectangle",
"description": "绘制安装板外轮廓 (120x80mm)，中心在原点",
"params": {
"x1": -0.06,
"y1": -0.04,
"x2": 0.06,
"y2": 0.04
}
},
{
"operation": "sketch_circle",
"description": "绘制左下角 Ø7 孔 (圆心距边 12mm)",
"params": {
"cx": -0.048,
"cy": -0.028,
"radius": 0.0035
}
},
{
"operation": "sketch_circle",
"description": "绘制右下角 Ø7 孔",
"params": {
"cx": 0.048,
"cy": -0.028,
"radius": 0.0035
}
},
{
"operation": "sketch_circle",
"description": "绘制右上角 Ø7 孔",
"params": {
"cx": 0.048,
"cy": 0.028,
"radius": 0.0035
}
},
{
"operation": "sketch_circle",
"description": "绘制左上角 Ø7 孔",
"params": {
"cx": -0.048,
"cy": 0.028,
"radius": 0.0035
}
},
{
"operation": "sketch_rectangle",
"description": "绘制中央 40x20mm 矩形窗口轮廓",
"params": {
"x1": -0.02,
"y1": -0.01,
"x2": 0.02,
"y2": 0.01
}
},
{
"operation": "feature_extrusion",
"description": "拉伸 6mm 厚度，草图中的外框形成实体，内圈圆和矩形自动形成贯穿孔",
"params": {
"depth": 0.006
}
},
{
"operation": "feature_fillet",
"description": "对左前竖直棱边做 R8 圆角",
"params": {
"radius": 0.008,
"edgeSelection": "front_left"
}
},
{
"operation": "feature_fillet",
"description": "对右前竖直棱边做 R8 圆角",
"params": {
"radius": 0.008,
"edgeSelection": "front_right"
}
},
{
"operation": "feature_fillet",
"description": "对左后竖直棱边做 R8 圆角",
"params": {
"radius": 0.008,
"edgeSelection": "back_left"
}
},
{
"operation": "feature_fillet",
"description": "对右后竖直棱边做 R8 圆角",
"params": {
"radius": 0.008,
"edgeSelection": "back_right"
}
}
]
}

{
"user_intent": "创建一个两层台阶块零件。下层尺寸 80x50x15mm，上层尺寸 40x50x15mm，上层与下层一端及两侧对齐。在下层露出的上表面中心加工一个直径 10mm、深 8mm 的盲孔。",
"notes": "单位已转换为米。建模策略：先在前视基准面绘制 L 形轮廓（合并两个矩形），一次拉伸 50mm 宽度形成台阶块主体。然后计算下层露出区域的中心坐标，使用射线选面进入草图，画圆并切除盲孔。",
"steps": [
{
"operation": "new_part",
"description": "新建零件文档",
"params": {}
},
